-- Generated by scripts/generateSeedSqlBasics.js from scripts/courseContent/basics.js.
-- Run once in the Supabase SQL Editor, after supabase/schema.sql.
-- Regenerate + re-run any time the content file changes (upserts are idempotent).

on conflict (id) do update set
  title = excluded.title, roman = excluded.roman, description = excluded.description, sort_order = excluded.sort_order;

delete from public.course_lessons where subject_id = $q$basics$q$ and id not in ($q$b01$q$, $q$b02$q$, $q$b03$q$, $q$b04$q$, $q$b05$q$, $q$b06$q$, $q$b07$q$, $q$b08$q$, $q$b09$q$, $q$b10$q$, $q$b-dlg$q$);

on conflict (id) do update set
  subject_id = excluded.subject_id, sort_order = excluded.sort_order, title = excluded.title, steps = excluded.steps;
