insert into public.course_subjects (id, title, roman, description, sort_order)
values
  ($q$basics$q$, $q$Basics: Everyday Sentences$q$, $q$phɯ́ɯn-thǎan$q$, $q$Real Thai sentence patterns from Essential Thai: this/that, adjectives, to be, yes/no and confirmation questions, colors, days of the week, and basic verbs.$q$, 3)
insert into public.course_lessons (id, subject_id, sort_order, title, steps)
values
  ($q$b01$q$, $q$basics$q$, 0, $q$This one, and how many?$q$, $j$[{"id":"rule-1","type":"rule","title":"This vs. this one","body":"Nîi (\"this\") alone has a falling tone. But when it's attached right after a classifier, as in \"this one\" (an-níi) or \"this person\", it takes a high tone instead.","source":"Essential Thai (Higbie), p.27"},{"id":"wi-2","type":"wordIntro","word":{"thai":"เอา","roman":"ao","english":"want / take"},"source":"Essential Thai (Higbie), p.27"},{"id":"wi-3","type":"wordIntro","word":{"thai":"นี่","roman":"nîi","english":"this"},"source":"Essential Thai (Higbie), p.27"},{"id":"sp-9","type":"speak","thai":"นี่","roman":"nîi","meaning":"this","source":"Essential Thai (Higbie), p.27","parts":["นี่"]},{"id":"wi-4","type":"wordIntro","word":{"thai":"อันนี้","roman":"an-níi","english":"this one"},"source":"Essential Thai (Higbie), p.27"},{"id":"mc-6","type":"translationChoice","thai":"เอาอันนี้","roman":"ao an-níi","options":[{"text":"I don't want it.","correct":false},{"text":"I want this one.","correct":true},{"text":"Which one do you want?","correct":false},{"text":"It's expensive.","correct":false}],"source":"Essential Thai (Higbie), p.27","parts":["เอา","อันนี้"]},{"id":"wi-5","type":"wordIntro","word":{"thai":"อันไหน","roman":"an-nǎi","english":"which one?"},"source":"Essential Thai (Higbie), p.27"},{"id":"so-7","type":"sentenceOrder","prompt":"Which one do you want?","tileUnit":"word","words":{"a":{"roman":"ao","thai":"เอา"},"b":{"roman":"an-nǎi","thai":"อันไหน"},"x0":{"thai":"นี่","roman":"nîi"},"x1":{"thai":"อันนี้","roman":"an-níi"}},"poolOrder":["x0","a","b","x1"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.27"},{"id":"mc-8","type":"translationChoice","thai":"อันไหน","roman":"an-nǎi","options":[{"text":"I don't want it.","correct":false},{"text":"It's beautiful.","correct":false},{"text":"This one.","correct":false},{"text":"Which one?","correct":true}],"source":"Essential Thai (Higbie), p.27","parts":["อันไหน"]},{"id":"wi-10","type":"wordIntro","word":{"thai":"กี่","roman":"gìi","english":"how many?"},"source":"Essential Thai (Higbie), p.28"},{"id":"wi-11","type":"wordIntro","word":{"thai":"อัน","roman":"an","english":"item (classifier for objects)"},"source":"Essential Thai (Higbie), p.28"},{"id":"mc-13","type":"translationChoice","thai":"เอากี่อัน","roman":"ao gìi an","options":[{"text":"I have one.","correct":false},{"text":"How many do you want?","correct":true},{"text":"I want this one.","correct":false},{"text":"Which one?","correct":false}],"source":"Essential Thai (Higbie), p.28","parts":["เอา","กี่","อัน"]},{"id":"sp-16","type":"speak","thai":"กี่อัน","roman":"gìi an","meaning":"how many (items)?","source":"Essential Thai (Higbie), p.28","parts":["กี่","อัน"]},{"id":"sp-17","type":"speak","thai":"เอากี่อัน","roman":"ao gìi an","meaning":"How many do you want?","source":"Essential Thai (Higbie), p.28","parts":["เอา","กี่","อัน"]},{"id":"rp-18","type":"reply","context":[{"speaker":"M","thai":"เอาอันไหน","parts":["เอา","อันไหน"],"roman":"ao an-nǎi","english":"Which one do you want?"}],"replySpeaker":"F","thai":"เอาอันนี้","roman":"ao an-níi","english":"I want this one.","options":[{"thai":"อันไหน","roman":"an-nǎi","correct":false},{"thai":"เอาอันนี้","roman":"ao an-níi","correct":true},{"thai":"เอากี่อัน","roman":"ao gìi an","correct":false}],"source":"Essential Thai (Higbie), p.27","parts":["เอา","อันนี้"]},{"id":"wi-12","type":"wordIntro","word":{"thai":"เดียว","roman":"diao","english":"single / only one"},"source":"Essential Thai (Higbie), p.28"},{"id":"so-14","type":"sentenceOrder","prompt":"I want just one.","tileUnit":"word","words":{"a":{"roman":"ao","thai":"เอา"},"b":{"roman":"an","thai":"อัน"},"c":{"roman":"diao","thai":"เดียว"},"x0":{"thai":"กี่","roman":"gìi"},"x1":{"thai":"อันไหน","roman":"an-nǎi"}},"poolOrder":["b","x1","c","x0","a"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.28"},{"id":"mc-15","type":"translationChoice","thai":"อันเดียว","roman":"an diao","options":[{"text":"How many?","correct":false},{"text":"A single one / just one.","correct":true},{"text":"Two items.","correct":false},{"text":"This one.","correct":false}],"source":"Essential Thai (Higbie), p.28","parts":["อัน","เดียว"]},{"id":"match-19","type":"match","pairs":[{"thai":"เอา","roman":"ao","english":"want / take"},{"thai":"นี่","roman":"nîi","english":"this"},{"thai":"อันนี้","roman":"an-níi","english":"this one"},{"thai":"อันไหน","roman":"an-nǎi","english":"which one?"},{"thai":"กี่","roman":"gìi","english":"how many?"},{"thai":"อัน","roman":"an","english":"item (classifier for objects)"},{"thai":"เดียว","roman":"diao","english":"single / only one"}],"source":"Essential Thai (Higbie), p.27"}]$j$::jsonb),
  ($q$b02$q$, $q$basics$q$, 1, $q$Yes/no, and confirming$q$, $j$[{"id":"rule-20","type":"rule","title":"Yes/no questions with mái","body":"Put mái after a verb to ask a yes/no question — it often works like an invitation (\"...mái?\" can mean \"want to...?\"). Answer \"yes\" by repeating the verb, or \"no\" by putting mâi in front of it.","source":"Essential Thai (Higbie), p.56"},{"id":"rule-28","type":"rule","title":"Confirming with châi mái","body":"Use châi mái at the end of a statement when you already think something is true and just want to confirm it, like English \"right?\". Answer châi (\"right\") or mâi châi (\"no, that's not right\").","source":"Essential Thai (Higbie), p.57"},{"id":"wi-21","type":"wordIntro","word":{"thai":"มั้ย","roman":"mái","english":"question particle (yes/no)"},"source":"Essential Thai (Higbie), p.56"},{"id":"mc-23","type":"translationChoice","thai":"เอามั้ย","roman":"ao mái","options":[{"text":"I want this one.","correct":false},{"text":"How many?","correct":false},{"text":"Do you want it?","correct":true},{"text":"This one.","correct":false}],"source":"Essential Thai (Higbie), p.56","parts":["เอา","มั้ย"]},{"id":"sp-26","type":"speak","thai":"มั้ย","roman":"mái","meaning":"question particle (yes/no)","source":"Essential Thai (Higbie), p.56","parts":["มั้ย"]},{"id":"wi-22","type":"wordIntro","word":{"thai":"ไม่","roman":"mâi","english":"not / no"},"source":"Essential Thai (Higbie), p.56"},{"id":"so-24","type":"sentenceOrder","prompt":"No, I don't want it.","tileUnit":"word","words":{"a":{"roman":"mâi","thai":"ไม่"},"b":{"roman":"ao","thai":"เอา"},"x0":{"thai":"กี่","roman":"gìi"},"x1":{"thai":"อันนี้","roman":"an-níi"}},"poolOrder":["x0","b","a","x1"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.56"},{"id":"mc-25","type":"translationChoice","thai":"ไม่เอา","roman":"mâi ao","options":[{"text":"Do you want it?","correct":false},{"text":"Just one.","correct":false},{"text":"No, I don't want it.","correct":true},{"text":"Which one?","correct":false}],"source":"Essential Thai (Higbie), p.56","parts":["ไม่","เอา"]},{"id":"sp-27","type":"speak","thai":"ไม่เอา","roman":"mâi ao","meaning":"No, I don't want it.","source":"Essential Thai (Higbie), p.56","parts":["ไม่","เอา"]},{"id":"wi-29","type":"wordIntro","word":{"thai":"ใช่","roman":"châi","english":"right / that's correct"},"source":"Essential Thai (Higbie), p.57"},{"id":"mc-30","type":"translationChoice","thai":"ใช่มั้ย","roman":"châi mái","options":[{"text":"Isn't that right?","correct":true},{"text":"I want this one.","correct":false},{"text":"No, that's not right.","correct":false},{"text":"How many?","correct":false}],"source":"Essential Thai (Higbie), p.57","parts":["ใช่","มั้ย"]},{"id":"so-31","type":"sentenceOrder","prompt":"No, that's not right.","tileUnit":"word","words":{"a":{"roman":"mâi","thai":"ไม่"},"b":{"roman":"châi","thai":"ใช่"},"x0":{"thai":"มั้ย","roman":"mái"},"x1":{"thai":"เอา","roman":"ao"}},"poolOrder":["x1","a","x0","b"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.57"},{"id":"mc-32","type":"translationChoice","thai":"ไม่ใช่","roman":"mâi châi","options":[{"text":"Do you want it?","correct":false},{"text":"Just one.","correct":false},{"text":"No, that's not right.","correct":true},{"text":"Yes, that's right.","correct":false}],"source":"Essential Thai (Higbie), p.57","parts":["ไม่","ใช่"]},{"id":"sp-33","type":"speak","thai":"ใช่","roman":"châi","meaning":"Yes, that's right.","source":"Essential Thai (Higbie), p.57","parts":["ใช่"]},{"id":"sp-34","type":"speak","thai":"ใช่มั้ย","roman":"châi mái","meaning":"Isn't that right?","source":"Essential Thai (Higbie), p.57","parts":["ใช่","มั้ย"]},{"id":"rp-35","type":"reply","context":[{"speaker":"M","thai":"เอามั้ย","parts":["เอา","มั้ย"],"roman":"ao mái","english":"Do you want it?"}],"replySpeaker":"F","thai":"ไม่เอา","roman":"mâi ao","english":"No, I don't want it.","options":[{"thai":"ใช่มั้ย","roman":"châi mái","correct":false},{"thai":"ไม่เอา","roman":"mâi ao","correct":true},{"thai":"อันไหน","roman":"an-nǎi","correct":false}],"source":"Essential Thai (Higbie), p.56","parts":["ไม่","เอา"]},{"id":"match-36","type":"match","pairs":[{"thai":"มั้ย","roman":"mái","english":"question particle (yes/no)"},{"thai":"ไม่","roman":"mâi","english":"not / no"},{"thai":"ใช่","roman":"châi","english":"right / that's correct"}],"source":"Essential Thai (Higbie), p.56"}]$j$::jsonb),
  ($q$b03$q$, $q$basics$q$, 2, $q$Tall, short, fat, thin$q$, $j$[{"id":"rule-37","type":"rule","title":"Describing people","body":"To describe someone, just put the adjective right after their name or a pronoun like \"you\" — Thai doesn't use a word for \"to be\" with adjectives.","source":"Essential Thai (Higbie), p.46"},{"id":"wi-38","type":"wordIntro","word":{"thai":"คุณ","roman":"khun","english":"you"},"source":"Essential Thai (Higbie), p.46"},{"id":"wi-39","type":"wordIntro","word":{"thai":"สูง","roman":"sǔung","english":"tall"},"source":"Essential Thai (Higbie), p.46"},{"id":"mc-41","type":"translationChoice","thai":"คุณสูงมั้ย","roman":"khun sǔung mái","options":[{"text":"Do you want it?","correct":false},{"text":"That's right.","correct":false},{"text":"You're short.","correct":false},{"text":"Are you tall?","correct":true}],"source":"Essential Thai (Higbie), p.46","parts":["คุณ","สูง","มั้ย"]},{"id":"wi-40","type":"wordIntro","word":{"thai":"เตี้ย","roman":"tîa","english":"short"},"source":"Essential Thai (Higbie), p.46"},{"id":"so-42","type":"sentenceOrder","prompt":"You're not short.","tileUnit":"word","words":{"a":{"roman":"khun","thai":"คุณ"},"b":{"roman":"mâi","thai":"ไม่"},"c":{"roman":"tîa","thai":"เตี้ย"},"x0":{"thai":"อันไหน","roman":"an-nǎi"},"x1":{"thai":"ใช่","roman":"châi"}},"poolOrder":["c","b","x0","a","x1"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.46"},{"id":"mc-43","type":"translationChoice","thai":"คุณเตี้ยมั้ย","roman":"khun tîa mái","options":[{"text":"Just one.","correct":false},{"text":"Are you short?","correct":true},{"text":"Which one?","correct":false},{"text":"You're tall.","correct":false}],"source":"Essential Thai (Higbie), p.46","parts":["คุณ","เตี้ย","มั้ย"]},{"id":"sp-44","type":"speak","thai":"คุณไม่เตี้ย","roman":"khun mâi tîa","meaning":"You're not short.","source":"Essential Thai (Higbie), p.46","parts":["คุณ","ไม่","เตี้ย"]},{"id":"wi-45","type":"wordIntro","word":{"thai":"อ้วน","roman":"ûan","english":"fat / well-built"},"source":"Essential Thai (Higbie), p.46"},{"id":"mc-50","type":"translationChoice","thai":"ไม่อ้วน","roman":"mâi ûan","options":[{"text":"Very tall.","correct":false},{"text":"Very thin.","correct":false},{"text":"Not fat.","correct":true},{"text":"Not short.","correct":false}],"source":"Essential Thai (Higbie), p.46","parts":["ไม่","อ้วน"]},{"id":"wi-46","type":"wordIntro","word":{"thai":"ผอม","roman":"phɔ̌ɔm","english":"thin"},"source":"Essential Thai (Higbie), p.46"},{"id":"wi-47","type":"wordIntro","word":{"thai":"มาก","roman":"mâak","english":"very / a lot"},"source":"Essential Thai (Higbie), p.46"},{"id":"mc-48","type":"translationChoice","thai":"คุณสูงมาก","roman":"khun sǔung mâak","options":[{"text":"You're not short.","correct":false},{"text":"You're very thin.","correct":false},{"text":"Are you tall?","correct":false},{"text":"You're very tall.","correct":true}],"source":"Essential Thai (Higbie), p.46","parts":["คุณ","สูง","มาก"]},{"id":"so-49","type":"sentenceOrder","prompt":"Very thin.","tileUnit":"word","words":{"a":{"roman":"phɔ̌ɔm","thai":"ผอม"},"b":{"roman":"mâak","thai":"มาก"},"x0":{"thai":"อันนี้","roman":"an-níi"},"x1":{"thai":"คุณ","roman":"khun"}},"poolOrder":["a","x1","x0","b"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.46"},{"id":"sp-51","type":"speak","thai":"ผอมมาก","roman":"phɔ̌ɔm mâak","meaning":"very thin","source":"Essential Thai (Higbie), p.46","parts":["ผอม","มาก"]},{"id":"rp-52","type":"reply","context":[{"speaker":"M","thai":"คุณสูงมั้ย","parts":["คุณ","สูง","มั้ย"],"roman":"khun sǔung mái","english":"Are you tall?"}],"replySpeaker":"F","thai":"ไม่สูง","roman":"mâi sǔung","english":"No, not tall.","options":[{"thai":"ไม่สูง","roman":"mâi sǔung","correct":true},{"thai":"ผอมมาก","roman":"phɔ̌ɔm mâak","correct":false},{"thai":"คุณเตี้ยมั้ย","roman":"khun tîa mái","correct":false}],"source":"Essential Thai (Higbie), p.46","parts":["ไม่","สูง"]},{"id":"match-53","type":"match","pairs":[{"thai":"คุณ","roman":"khun","english":"you"},{"thai":"สูง","roman":"sǔung","english":"tall"},{"thai":"เตี้ย","roman":"tîa","english":"short"},{"thai":"อ้วน","roman":"ûan","english":"fat / well-built"},{"thai":"ผอม","roman":"phɔ̌ɔm","english":"thin"},{"thai":"มาก","roman":"mâak","english":"very / a lot"}],"source":"Essential Thai (Higbie), p.46"}]$j$::jsonb),
  ($q$b04$q$, $q$basics$q$, 3, $q$Beautiful, clean, rich$q$, $j$[{"id":"wi-54","type":"wordIntro","word":{"thai":"สวย","roman":"sǔai","english":"beautiful"},"source":"Essential Thai (Higbie), p.46"},{"id":"mc-57","type":"translationChoice","thai":"คุณสวยมาก","roman":"khun sǔai mâak","options":[{"text":"Handsome.","correct":false},{"text":"You're very beautiful.","correct":true},{"text":"Not fat.","correct":false},{"text":"You're very tall.","correct":false}],"source":"Essential Thai (Higbie), p.46","parts":["คุณ","สวย","มาก"]},{"id":"wi-55","type":"wordIntro","word":{"thai":"หล่อ","roman":"lɔ̀ɔ","english":"handsome"},"source":"Essential Thai (Higbie), p.46"},{"id":"so-58","type":"sentenceOrder","prompt":"Very handsome.","tileUnit":"word","words":{"a":{"roman":"lɔ̀ɔ","thai":"หล่อ"},"b":{"roman":"mâak","thai":"มาก"},"x0":{"thai":"นี่","roman":"nîi"},"x1":{"thai":"ผอม","roman":"phɔ̌ɔm"}},"poolOrder":["x0","x1","a","b"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.46"},{"id":"mc-59","type":"translationChoice","thai":"ไม่หล่อ","roman":"mâi lɔ̀ɔ","options":[{"text":"Not handsome.","correct":true},{"text":"Beautiful.","correct":false},{"text":"Very cute.","correct":false},{"text":"Tall.","correct":false}],"source":"Essential Thai (Higbie), p.46","parts":["ไม่","หล่อ"]},{"id":"wi-56","type":"wordIntro","word":{"thai":"น่ารัก","roman":"nâa-rák","english":"cute / lovable"},"source":"Essential Thai (Higbie), p.46"},{"id":"sp-60","type":"speak","thai":"น่ารักมาก","roman":"nâa-rák mâak","meaning":"very cute","source":"Essential Thai (Higbie), p.46","parts":["น่ารัก","มาก"]},{"id":"wi-61","type":"wordIntro","word":{"thai":"สะอาด","roman":"sà-àat","english":"clean"},"source":"Essential Thai (Higbie), p.46"},{"id":"mc-64","type":"translationChoice","thai":"สะอาดมั้ย","roman":"sà-àat mái","options":[{"text":"Handsome.","correct":false},{"text":"Very poor.","correct":false},{"text":"Is it clean?","correct":true},{"text":"Not clean.","correct":false}],"source":"Essential Thai (Higbie), p.46","parts":["สะอาด","มั้ย"]},{"id":"so-65","type":"sentenceOrder","prompt":"Not clean.","tileUnit":"word","words":{"a":{"roman":"mâi","thai":"ไม่"},"b":{"roman":"sà-àat","thai":"สะอาด"},"x0":{"thai":"นี่","roman":"nîi"},"x1":{"thai":"อันนี้","roman":"an-níi"}},"poolOrder":["a","b","x1","x0"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.46"},{"id":"sp-67","type":"speak","thai":"สะอาดมาก","roman":"sà-àat mâak","meaning":"very clean","source":"Essential Thai (Higbie), p.46","parts":["สะอาด","มาก"]},{"id":"wi-62","type":"wordIntro","word":{"thai":"รวย","roman":"ruai","english":"rich"},"source":"Essential Thai (Higbie), p.46"},{"id":"mc-66","type":"translationChoice","thai":"คุณรวยมาก","roman":"khun ruai mâak","options":[{"text":"You're very rich.","correct":true},{"text":"Very cute.","correct":false},{"text":"You're poor.","correct":false},{"text":"Very clean.","correct":false}],"source":"Essential Thai (Higbie), p.46","parts":["คุณ","รวย","มาก"]},{"id":"rp-68","type":"reply","context":[{"speaker":"M","thai":"สะอาดมั้ย","parts":["สะอาด","มั้ย"],"roman":"sà-àat mái","english":"Is it clean?"}],"replySpeaker":"F","thai":"ไม่สะอาด","roman":"mâi sà-àat","english":"No, it's not clean.","options":[{"thai":"คุณรวยมาก","roman":"khun ruai mâak","correct":false},{"thai":"ไม่หล่อ","roman":"mâi lɔ̀ɔ","correct":false},{"thai":"ไม่สะอาด","roman":"mâi sà-àat","correct":true}],"source":"Essential Thai (Higbie), p.46","parts":["ไม่","สะอาด"]},{"id":"wi-63","type":"wordIntro","word":{"thai":"จน","roman":"jon","english":"poor"},"source":"Essential Thai (Higbie), p.46"},{"id":"match-69","type":"match","pairs":[{"thai":"สวย","roman":"sǔai","english":"beautiful"},{"thai":"หล่อ","roman":"lɔ̀ɔ","english":"handsome"},{"thai":"น่ารัก","roman":"nâa-rák","english":"cute / lovable"},{"thai":"สะอาด","roman":"sà-àat","english":"clean"},{"thai":"รวย","roman":"ruai","english":"rich"},{"thai":"จน","roman":"jon","english":"poor"}],"source":"Essential Thai (Higbie), p.46"}]$j$::jsonb),
  ($q$b05$q$, $q$basics$q$, 4, $q$To be, and 'this ___'$q$, $j$[{"id":"rule-70","type":"rule","title":"Two ways to say \"is\"","body":"Keu links two things that are exactly equivalent (it's usually left out in speech). Pen links a subject to a describing noun, like a job or relationship — but not to an adjective. To say a noun sentence is false, use mâi châi, not mâi alone.","source":"Essential Thai (Higbie), p.47"},{"id":"rule-78","type":"rule","title":"\"This ___\"","body":"Put níi (high tone) right after a noun to say \"this ___\". There's no separate word for \"the\" in Thai — just say the name of the thing.","source":"Essential Thai (Higbie), p.49"},{"id":"wi-71","type":"wordIntro","word":{"thai":"เป็น","roman":"pen","english":"to be / is"},"source":"Essential Thai (Higbie), p.47"},{"id":"wi-72","type":"wordIntro","word":{"thai":"เค้า","roman":"kháo","english":"he / she"},"source":"Essential Thai (Higbie), p.47"},{"id":"wi-73","type":"wordIntro","word":{"thai":"เพื่อน","roman":"phɯ̂an","english":"friend"},"source":"Essential Thai (Higbie), p.47"},{"id":"mc-74","type":"translationChoice","thai":"เค้าเป็นเพื่อน","roman":"kháo pen phɯ̂an","options":[{"text":"He's not a friend.","correct":false},{"text":"He's/she's a friend.","correct":true},{"text":"You're rich.","correct":false},{"text":"Is it clean?","correct":false}],"source":"Essential Thai (Higbie), p.47","parts":["เค้า","เป็น","เพื่อน"]},{"id":"so-75","type":"sentenceOrder","prompt":"She's not a friend.","tileUnit":"word","words":{"a":{"roman":"kháo","thai":"เค้า"},"b":{"roman":"mâi","thai":"ไม่"},"c":{"roman":"châi","thai":"ใช่"},"d":{"roman":"phɯ̂an","thai":"เพื่อน"},"x0":{"thai":"สะอาด","roman":"sà-àat"},"x1":{"thai":"ผอม","roman":"phɔ̌ɔm"}},"poolOrder":["d","c","b","x1","a","x0"],"correctOrder":["a","b","c","d"],"source":"Essential Thai (Higbie), p.47"},{"id":"mc-76","type":"translationChoice","thai":"เค้าไม่ใช่เพื่อน","roman":"kháo mâi châi phɯ̂an","options":[{"text":"He's/she's not a friend.","correct":true},{"text":"He's a friend.","correct":false},{"text":"You're very beautiful.","correct":false},{"text":"A single one.","correct":false}],"source":"Essential Thai (Higbie), p.47","parts":["เค้า","ไม่","ใช่","เพื่อน"]},{"id":"sp-77","type":"speak","thai":"เค้าเป็นเพื่อน","roman":"kháo pen phɯ̂an","meaning":"He's/she's a friend.","source":"Essential Thai (Higbie), p.47","parts":["เค้า","เป็น","เพื่อน"]},{"id":"wi-79","type":"wordIntro","word":{"thai":"เสื้อ","roman":"sɯ̂a","english":"shirt"},"source":"Essential Thai (Higbie), p.49"},{"id":"wi-80","type":"wordIntro","word":{"thai":"นี้","roman":"níi","english":"this (after a noun)"},"source":"Essential Thai (Higbie), p.49"},{"id":"mc-84","type":"translationChoice","thai":"เสื้อนี้สวย","roman":"sɯ̂a níi sǔai","options":[{"text":"This shirt is beautiful.","correct":true},{"text":"This hotel is expensive.","correct":false},{"text":"Very rich.","correct":false},{"text":"He's a friend.","correct":false}],"source":"Essential Thai (Higbie), p.49","parts":["เสื้อ","นี้","สวย"]},{"id":"wi-81","type":"wordIntro","word":{"thai":"โรงแรม","roman":"rong-raem","english":"hotel"},"source":"Essential Thai (Higbie), p.49"},{"id":"wi-82","type":"wordIntro","word":{"thai":"แพง","roman":"phaeng","english":"expensive"},"source":"Essential Thai (Higbie), p.49"},{"id":"so-85","type":"sentenceOrder","prompt":"This hotel is expensive.","tileUnit":"word","words":{"a":{"roman":"rong-raem","thai":"โรงแรม"},"b":{"roman":"níi","thai":"นี้"},"c":{"roman":"phaeng","thai":"แพง"},"x0":{"thai":"กี่","roman":"gìi"},"x1":{"thai":"คุณ","roman":"khun"}},"poolOrder":["b","x1","c","a","x0"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.49"},{"id":"mc-86","type":"translationChoice","thai":"โรงแรมนี้แพงมั้ย","roman":"rong-raem níi phaeng mái","options":[{"text":"Not clean.","correct":false},{"text":"This shirt is beautiful.","correct":false},{"text":"He's a friend.","correct":false},{"text":"Is this hotel expensive?","correct":true}],"source":"Essential Thai (Higbie), p.49","parts":["โรงแรม","นี้","แพง","มั้ย"]},{"id":"rp-88","type":"reply","context":[{"speaker":"M","thai":"โรงแรมนี้แพงมั้ย","parts":["โรงแรม","นี้","แพง","มั้ย"],"roman":"rong-raem níi phaeng mái","english":"Is this hotel expensive?"}],"replySpeaker":"F","thai":"ไม่แพง","roman":"mâi phaeng","english":"No, it's not expensive.","options":[{"thai":"เค้าเป็นเพื่อน","roman":"kháo pen phɯ̂an","correct":false},{"thai":"เสื้อนี้สวย","roman":"sɯ̂a níi sǔai","correct":false},{"thai":"ไม่แพง","roman":"mâi phaeng","correct":true}],"source":"Essential Thai (Higbie), p.49","parts":["ไม่","แพง"]},{"id":"wi-83","type":"wordIntro","word":{"thai":"แล้วก็","roman":"láew-gɔ̂ɔ","english":"and then / also"},"source":"Essential Thai (Higbie), general reference (connecting words)"},{"id":"sp-87","type":"speak","thai":"เสื้อนี้สวยแล้วก็ไม่แพง","roman":"sɯ̂a níi sǔai láew-gɔ̂ɔ mâi phaeng","meaning":"This shirt is beautiful, and it's not expensive.","source":"Essential Thai (Higbie), p.49","parts":["เสื้อ","นี้","สวย","แล้วก็","ไม่","แพง"]},{"id":"match-89","type":"match","pairs":[{"thai":"เป็น","roman":"pen","english":"to be / is"},{"thai":"เค้า","roman":"kháo","english":"he / she"},{"thai":"เพื่อน","roman":"phɯ̂an","english":"friend"},{"thai":"เสื้อ","roman":"sɯ̂a","english":"shirt"},{"thai":"นี้","roman":"níi","english":"this (after a noun)"},{"thai":"โรงแรม","roman":"rong-raem","english":"hotel"},{"thai":"แพง","roman":"phaeng","english":"expensive"},{"thai":"แล้วก็","roman":"láew-gɔ̂ɔ","english":"and then / also"}],"source":"Essential Thai (Higbie), p.47"}]$j$::jsonb),
  ($q$b06$q$, $q$basics$q$, 5, $q$The same, or too much$q$, $j$[{"id":"rule-90","type":"rule","title":"The same as","body":"Meuan means \"the same as\" or \"like\". Add gan (\"each other\") when you're saying two things are the same, especially at the end of a sentence.","source":"Essential Thai (Higbie), p.49"},{"id":"rule-97","type":"rule","title":"Too ___","body":"Add pai right after an adjective to say \"too ___\" — the same word pai also means \"go\", but here it works as an intensifier.","source":"Essential Thai (Higbie), p.48"},{"id":"wi-91","type":"wordIntro","word":{"thai":"เหมือน","roman":"mɯ̌an","english":"the same as / like"},"source":"Essential Thai (Higbie), p.49"},{"id":"mc-95","type":"translationChoice","thai":"คุณเหมือนเค้า","roman":"khun mɯ̌an kháo","options":[{"text":"You're like him/her.","correct":true},{"text":"A single one.","correct":false},{"text":"This hotel is expensive.","correct":false},{"text":"They're the same.","correct":false}],"source":"Essential Thai (Higbie), p.49","parts":["คุณ","เหมือน","เค้า"]},{"id":"wi-92","type":"wordIntro","word":{"thai":"กัน","roman":"gan","english":"each other / together"},"source":"Essential Thai (Higbie), p.49"},{"id":"mc-93","type":"translationChoice","thai":"เหมือนกัน","roman":"mɯ̌an gan","options":[{"text":"This shirt is beautiful.","correct":false},{"text":"He's a friend.","correct":false},{"text":"They're not the same.","correct":false},{"text":"They're the same.","correct":true}],"source":"Essential Thai (Higbie), p.49","parts":["เหมือน","กัน"]},{"id":"so-94","type":"sentenceOrder","prompt":"Not the same.","tileUnit":"word","words":{"a":{"roman":"mâi","thai":"ไม่"},"b":{"roman":"mɯ̌an","thai":"เหมือน"},"c":{"roman":"gan","thai":"กัน"},"x0":{"thai":"ใช่","roman":"châi"},"x1":{"thai":"ผอม","roman":"phɔ̌ɔm"}},"poolOrder":["b","x0","c","a","x1"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.49"},{"id":"sp-96","type":"speak","thai":"ไม่เหมือนกัน","roman":"mâi mɯ̌an gan","meaning":"not the same","source":"Essential Thai (Higbie), p.49","parts":["ไม่","เหมือน","กัน"]},{"id":"wi-98","type":"wordIntro","word":{"thai":"ไป","roman":"pai","english":"go / too (after an adjective)"},"source":"Essential Thai (Higbie), p.48"},{"id":"mc-101","type":"translationChoice","thai":"แพงไป","roman":"phaeng pai","options":[{"text":"Too small.","correct":false},{"text":"Very beautiful.","correct":false},{"text":"It's too expensive.","correct":true},{"text":"Not expensive.","correct":false}],"source":"Essential Thai (Higbie), p.48","parts":["แพง","ไป"]},{"id":"sp-103","type":"speak","thai":"แพงไป","roman":"phaeng pai","meaning":"too expensive","source":"Essential Thai (Higbie), p.48","parts":["แพง","ไป"]},{"id":"wi-99","type":"wordIntro","word":{"thai":"เล็ก","roman":"lék","english":"small"},"source":"Essential Thai (Higbie), p.48"},{"id":"mc-100","type":"translationChoice","thai":"เล็กไป","roman":"lék pai","options":[{"text":"It's too small.","correct":true},{"text":"That's not right.","correct":false},{"text":"Too expensive.","correct":false},{"text":"Very small.","correct":false}],"source":"Essential Thai (Higbie), p.48","parts":["เล็ก","ไป"]},{"id":"so-102","type":"sentenceOrder","prompt":"This shirt is too small.","tileUnit":"word","words":{"a":{"roman":"sɯ̂a","thai":"เสื้อ"},"b":{"roman":"níi","thai":"นี้"},"c":{"roman":"lék","thai":"เล็ก"},"d":{"roman":"pai","thai":"ไป"},"x0":{"thai":"อันไหน","roman":"an-nǎi"},"x1":{"thai":"หล่อ","roman":"lɔ̀ɔ"}},"poolOrder":["d","c","a","x1","x0","b"],"correctOrder":["a","b","c","d"],"source":"Essential Thai (Higbie), p.48"},{"id":"rp-104","type":"reply","context":[{"speaker":"M","thai":"เอาอันนี้มั้ย","parts":["เอา","อันนี้","มั้ย"],"roman":"ao an-níi mái","english":"Do you want this one?"}],"replySpeaker":"F","thai":"ไม่เอาเล็กไป","roman":"mâi ao, lék pai","english":"No, it's too small.","options":[{"thai":"คุณเหมือนเค้า","roman":"khun mɯ̌an kháo","correct":false},{"thai":"เหมือนกัน","roman":"mɯ̌an gan","correct":false},{"thai":"ไม่เอาเล็กไป","roman":"mâi ao, lék pai","correct":true}],"source":"Essential Thai (Higbie), p.48","parts":["ไม่","เอา","เล็ก","ไป"]},{"id":"match-105","type":"match","pairs":[{"thai":"เหมือน","roman":"mɯ̌an","english":"the same as / like"},{"thai":"กัน","roman":"gan","english":"each other / together"},{"thai":"ไป","roman":"pai","english":"go / too (after an adjective)"},{"thai":"เล็ก","roman":"lék","english":"small"}],"source":"Essential Thai (Higbie), p.49"}]$j$::jsonb),
  ($q$b07$q$, $q$basics$q$, 6, $q$Colors, have to, can$q$, $j$[{"id":"rule-106","type":"rule","title":"Colors","body":"Put sǐi (\"color\") before any color word — then put the whole color word after the name of the object it describes.","source":"Essential Thai (Higbie), p.19"},{"id":"rule-115","type":"rule","title":"Have to / can","body":"Put tɔ̂ng right before a verb for \"have to/must\". Dâi means \"can\" for permission, availability, or ability — answer mâi dâi for \"can't\".","source":"Essential Thai (Higbie), p.59"},{"id":"wi-107","type":"wordIntro","word":{"thai":"สี","roman":"sǐi","english":"color"},"source":"Essential Thai (Higbie), p.19"},{"id":"wi-108","type":"wordIntro","word":{"thai":"แดง","roman":"dɛɛng","english":"red"},"source":"Essential Thai (Higbie), p.19"},{"id":"mc-111","type":"translationChoice","thai":"เสื้อสีแดง","roman":"sɯ̂a sǐi dɛɛng","options":[{"text":"a black shirt","correct":false},{"text":"a white shirt","correct":false},{"text":"This shirt is beautiful.","correct":false},{"text":"a red shirt","correct":true}],"source":"Essential Thai (Higbie), p.19","parts":["เสื้อ","สี","แดง"]},{"id":"sp-114","type":"speak","thai":"สีแดง","roman":"sǐi dɛɛng","meaning":"red","source":"Essential Thai (Higbie), p.19","parts":["สี","แดง"]},{"id":"wi-109","type":"wordIntro","word":{"thai":"ดำ","roman":"dam","english":"black"},"source":"Essential Thai (Higbie), p.19"},{"id":"so-112","type":"sentenceOrder","prompt":"A black shirt.","tileUnit":"word","words":{"a":{"roman":"sɯ̂a","thai":"เสื้อ"},"b":{"roman":"sǐi","thai":"สี"},"c":{"roman":"dam","thai":"ดำ"},"x0":{"thai":"เป็น","roman":"pen"},"x1":{"thai":"ผอม","roman":"phɔ̌ɔm"}},"poolOrder":["c","a","x1","x0","b"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.19"},{"id":"wi-110","type":"wordIntro","word":{"thai":"ขาว","roman":"khǎao","english":"white"},"source":"Essential Thai (Higbie), p.19"},{"id":"mc-113","type":"translationChoice","thai":"เสื้อสีขาวสวย","roman":"sɯ̂a sǐi khǎao sǔai","options":[{"text":"The white shirt is beautiful.","correct":true},{"text":"The red shirt is expensive.","correct":false},{"text":"a black shirt","correct":false},{"text":"too small","correct":false}],"source":"Essential Thai (Higbie), p.19","parts":["เสื้อ","สี","ขาว","สวย"]},{"id":"wi-116","type":"wordIntro","word":{"thai":"ต้อง","roman":"tɔ̂ng","english":"have to / must"},"source":"Essential Thai (Higbie), p.59"},{"id":"mc-118","type":"translationChoice","thai":"ต้องไป","roman":"tɔ̂ng pai","options":[{"text":"Too small.","correct":false},{"text":"I have to go.","correct":true},{"text":"A red shirt.","correct":false},{"text":"I can't go.","correct":false}],"source":"Essential Thai (Higbie), p.59","parts":["ต้อง","ไป"]},{"id":"wi-117","type":"wordIntro","word":{"thai":"ได้","roman":"dâi","english":"can / able to"},"source":"Essential Thai (Higbie), p.59"},{"id":"so-119","type":"sentenceOrder","prompt":"I can't go.","tileUnit":"word","words":{"a":{"roman":"pai","thai":"ไป"},"b":{"roman":"mâi","thai":"ไม่"},"c":{"roman":"dâi","thai":"ได้"},"x0":{"thai":"มาก","roman":"mâak"},"x1":{"thai":"เอา","roman":"ao"}},"poolOrder":["x1","b","x0","a","c"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.59"},{"id":"mc-120","type":"translationChoice","thai":"ไปได้มั้ย","roman":"pai dâi mái","options":[{"text":"Can you go?","correct":true},{"text":"A black shirt.","correct":false},{"text":"I have to go.","correct":false},{"text":"The color white.","correct":false}],"source":"Essential Thai (Higbie), p.59","parts":["ไป","ได้","มั้ย"]},{"id":"sp-121","type":"speak","thai":"ไปไม่ได้","roman":"pai mâi dâi","meaning":"I can't go.","source":"Essential Thai (Higbie), p.59","parts":["ไป","ไม่","ได้"]},{"id":"rp-122","type":"reply","context":[{"speaker":"M","thai":"ไปได้มั้ย","parts":["ไป","ได้","มั้ย"],"roman":"pai dâi mái","english":"Can you go?"}],"replySpeaker":"F","thai":"ไปไม่ได้","roman":"pai mâi dâi","english":"No, I can't go.","options":[{"thai":"ไปไม่ได้","roman":"pai mâi dâi","correct":true},{"thai":"เสื้อสีดำ","roman":"sɯ̂a sǐi dam","correct":false},{"thai":"สีขาว","roman":"sǐi khǎao","correct":false}],"source":"Essential Thai (Higbie), p.59","parts":["ไป","ไม่","ได้"]},{"id":"match-123","type":"match","pairs":[{"thai":"สี","roman":"sǐi","english":"color"},{"thai":"แดง","roman":"dɛɛng","english":"red"},{"thai":"ดำ","roman":"dam","english":"black"},{"thai":"ขาว","roman":"khǎao","english":"white"},{"thai":"ต้อง","roman":"tɔ̂ng","english":"have to / must"},{"thai":"ได้","roman":"dâi","english":"can / able to"}],"source":"Essential Thai (Higbie), p.19"}]$j$::jsonb),
  ($q$b08$q$, $q$basics$q$, 7, $q$Want to, like to, and doing what$q$, $j$[{"id":"rule-124","type":"rule","title":"Want to / like to","body":"\"Want to\" before a verb is yàak, not ao — ao is only for wanting an object, not an action. Chɔ̂ɔp before a verb means \"like to\" (or \"always do\").","source":"Essential Thai (Higbie), p.58"},{"id":"wi-125","type":"wordIntro","word":{"thai":"อยาก","roman":"yàak","english":"want to (+ verb)"},"source":"Essential Thai (Higbie), p.58"},{"id":"mc-127","type":"translationChoice","thai":"อยากไป","roman":"yàak pai","options":[{"text":"I have to go.","correct":false},{"text":"I like to go.","correct":false},{"text":"I don't want to go.","correct":false},{"text":"I want to go.","correct":true}],"source":"Essential Thai (Higbie), p.58","parts":["อยาก","ไป"]},{"id":"so-128","type":"sentenceOrder","prompt":"I don't want to go.","tileUnit":"word","words":{"a":{"roman":"mâi","thai":"ไม่"},"b":{"roman":"yàak","thai":"อยาก"},"c":{"roman":"pai","thai":"ไป"},"x0":{"thai":"เดียว","roman":"diao"},"x1":{"thai":"เอา","roman":"ao"}},"poolOrder":["c","x1","a","x0","b"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.58"},{"id":"sp-130","type":"speak","thai":"อยากไป","roman":"yàak pai","meaning":"I want to go.","source":"Essential Thai (Higbie), p.58","parts":["อยาก","ไป"]},{"id":"wi-126","type":"wordIntro","word":{"thai":"ชอบ","roman":"chɔ̂ɔp","english":"like to (+ verb) / like"},"source":"Essential Thai (Higbie), p.58"},{"id":"mc-129","type":"translationChoice","thai":"ไม่ชอบไป","roman":"mâi chɔ̂ɔp pai","options":[{"text":"I like to go.","correct":false},{"text":"I can't go.","correct":false},{"text":"I want to go.","correct":false},{"text":"I don't like to go.","correct":true}],"source":"Essential Thai (Higbie), p.58","parts":["ไม่","ชอบ","ไป"]},{"id":"wi-131","type":"wordIntro","word":{"thai":"มา","roman":"maa","english":"come"},"source":"Essential Thai (Higbie), p.54"},{"id":"wi-132","type":"wordIntro","word":{"thai":"กิน","r