  ($q$b09$q$, $q$basics$q$, 8, $q$Daily verbs: where and when$q$, $j$[{"id":"rule-148","type":"rule","title":"Where is...?","body":"Yùu means \"to be at a place\". Put thîi-nǎi (\"where?\") after yùu to ask where something is.","source":"Essential Thai (Higbie), p.31"},{"id":"wi-141","type":"wordIntro","word":{"thai":"ดู","roman":"duu","english":"see / look at / watch"},"source":"Essential Thai (Higbie), p.54"},{"id":"wi-142","type":"wordIntro","word":{"thai":"เดิน","roman":"dəən","english":"walk"},"source":"Essential Thai (Higbie), p.54"},{"id":"mc-146","type":"translationChoice","thai":"ชอบเดิน","roman":"chɔ̂ɔp dəən","options":[{"text":"Come and eat.","correct":false},{"text":"I want to watch.","correct":false},{"text":"I'm going to sleep.","correct":false},{"text":"I like to walk.","correct":true}],"source":"Essential Thai (Higbie), p.54","parts":["ชอบ","เดิน"]},{"id":"wi-143","type":"wordIntro","word":{"thai":"นอน","roman":"nɔɔn","english":"sleep"},"source":"Essential Thai (Higbie), p.54"},{"id":"mc-144","type":"translationChoice","thai":"ไปนอน","roman":"pai nɔɔn","options":[{"text":"Come and eat.","correct":false},{"text":"I like to walk.","correct":false},{"text":"What are you doing?","correct":false},{"text":"I'm going to sleep.","correct":true}],"source":"Essential Thai (Higbie), p.54","parts":["ไป","นอน"]},{"id":"so-145","type":"sentenceOrder","prompt":"I want to sleep.","tileUnit":"word","words":{"a":{"roman":"yàak","thai":"อยาก"},"b":{"roman":"nɔɔn","thai":"นอน"},"x0":{"thai":"สี","roman":"sǐi"},"x1":{"thai":"ผอม","roman":"phɔ̌ɔm"}},"poolOrder":["x0","a","b","x1"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.54"},{"id":"sp-147","type":"speak","thai":"ไปนอน","roman":"pai nɔɔn","meaning":"I'm going to sleep.","source":"Essential Thai (Higbie), p.54","parts":["ไป","นอน"]},{"id":"wi-149","type":"wordIntro","word":{"thai":"อยู่","roman":"yùu","english":"be at / stay"},"source":"Essential Thai (Higbie), p.31"},{"id":"wi-150","type":"wordIntro",