  ($q$b10$q$, $q$basics$q$, 9, $q$Days of the week, and who$q$, $j$[{"id":"rule-158","type":"rule","title":"Days of the week","body":"Every day name starts with wan (\"day\"). To ask which day, put wan-nǎi (\"which day?\") at the end of the question — pai wan-nǎi is \"What day are you going?\"","source":"Essential Thai (Higbie), p.98"},{"id":"wi-159","type":"wordIntro","word":{"thai":"วันจันทร์","roman":"wan-jan","english":"Monday"},"source":"Essential Thai (Higbie), p.98"},{"id":"mc-163","type":"translationChoice","thai":"ไปวันจันทร์","roman":"pai wan-jan","options":[{"text":"I'm going on Friday.","correct":false},{"text":"I'm going on Sunday.","correct":false},{"text":"I'm going on Monday.","correct":true},{"text":"What day?","correct":false}],"source":"Essential Thai (Higbie), p.98","parts":["ไป","วันจันทร์"]},{"id":"wi-160","type":"wordIntro","word":{"thai":"วันศุกร์","roman":"wan-sùk","english":"Friday"},"source":"Essential Thai (Higbie), p.98"},{"id":"so-164","type":"sentenceOrder","prompt":"I'm going on Friday.","tileUnit":"word","words":{"a":{"roman":"pai","thai":"ไป"},"b":{"roman":"wan-sùk","thai":"วันศุกร์"},"x0":{"thai":"ต้อง","roman":"tɔ̂ng"},"x1":{"thai":"มั้ย","roman":"mái"}},"poolOrder":["x1","a","b","x0"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.98"},{"id":"wi-161","type":"wordIntro","word":{"thai":"วันอาทิตย์","roman":"wan-aa-thít","english":"Sunday"},"source":"Essential Thai (Higbie), p.98"},{"id":"sp-166","type":"speak","thai":"วันอาทิตย์","roman":"wan-aa-thít","meaning":"Sunday","source":"Essential Thai (Higbie), p.98","parts":["วันอาทิตย์"]},{"id":"wi-162","type":"wordIntro","word":{"thai":"วันไหน","roman":"wan-nǎi","english":"what day?"},"source":"Essential Thai (Higbie), p.98"},{"id":"mc-165","type":"translationChoice","thai":"ไปวันไหน","roman":"pai wan-nǎi","options":[{"text":"Monday.","correct":false},{"text":"What day are you going?","correct":true},{"text":"When?","correct":false},{"text":"Sunday.","correct":false}],"s